protected void set(String name, String[] values) {
    // TODO: optimize this to not copy if all
    // values are to be included "as is"
    if (values != null) {
        metadata.remove(name);
        for (String v : values) {
            addTrusted(name, v);
        }
    } else {
        metadata.remove(name);
    }
}
